import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final int MAX = 31;
    static final long MOD = 1000000007L;
    static int n;
    static long[][] matrix = new long[MAX][MAX];

    static class Mat {
        long[][] t = new long[MAX][MAX];

        void init() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    t[i][j] = (i == j) ? 1 : 0;
                }
            }
        }

        void multiply(Mat b) {
            long[][] temp = new long[MAX][MAX];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    temp[i][j] = 0;
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        temp[i][k] = (temp[i][k] + this.t[i][j] * b.t[j][k]) % MOD;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                System.arraycopy(temp[i], 0, this.t[i], 0, n);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long m_input = sc.nextLong();
        int k_input = sc.nextInt();
        long m = m_input;
        int k = k_input;

        List<Long> digitsList = new ArrayList<>();
        while (m != 0) {
            digitsList.add(m % k);
            m /= k;
        }

        n = k + 1;

        Mat baseMat = new Mat();
        for (int i = 0; i < k; i++) {
            baseMat.t[i][(i + 1) % k] = 1;
        }
        baseMat.t[k][k] = 1;

        Mat identityMat = new Mat();
        identityMat.init();

        for (int i = 0; i <= k; i++) {
            baseMat.t[0][i] = 1;
            baseMat.t[i][i] = 1;
        }

        int size = digitsList.size();
        List<Mat> dMat = new ArrayList<>(size);
        dMat.add(new Mat());
        dMat.set(0, new Mat());
        dMat.get(0).init();
        dMat.get(0).multiply(baseMat);

        for (int i = 1; i < size; i++) {
            Mat prev = dMat.get(i - 1);
            Mat current = new Mat();
            current.t = new long[n][n];
            // Copy previous matrix
            for (int r = 0; r < n; r++) {
                System.arraycopy(prev.t[r], 0, current.t[r], 0, n);
            }
            // Square the matrix k times
            for (int _ = 0; _ < k; _++) {
                current.multiply(current);
            }
            current.multiply(baseMat);
            dMat.add(current);
        }

        long[] answerArr = new long[n];
        for (int i = 0; i < n; i++) {
            answerArr[i] = 1;
        }

        for (int idx = size - 1; idx >= 0; idx--) {
            long[] powerArr = new long[n];
            for (int _ = 0; _ < digitsList.get(idx); _++) {
                for (int i = 0; i < n; i++) {
                    powerArr[i] = 0;
                }
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        powerArr[j] = (powerArr[j] + answerArr[i] * dMat.get(idx).t[i][j]) % MOD;
                    }
                }
                System.arraycopy(powerArr, 0, answerArr, 0, n);
            }
        }

        System.out.println(answerArr[k]);
        sc.close();
    }
}

